from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    sep_rows=[r for r,row in enumerate(grid) if len(set(row))==1]
    sep_cols=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1]
    def spans(n,seps):
        out=[]; start=0
        for i in seps:
            if start<i: out.append((start,i))
            start=i+1
        if start<n: out.append((start,n))
        return out
    rs,cs=spans(h,sep_rows),spans(w,sep_cols)
    result=[]
    for r0,r1 in rs:
        row=[]
        for c0,c1 in cs:
            vals=[grid[r][c] for r in range(r0,r1) for c in range(c0,c1)]
            bg=Counter(vals).most_common(1)[0][0]
            n_special=sum(v!=bg for v in vals)
            row.append(1 if n_special==2 else bg)
        result.append(row)
    return result

